package com.ruoyi.hexu;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;
import java.util.*;
import static com.ruoyi.hexu.HexuStore.*;
import static com.ruoyi.hexu.BusinessException.require;
@Service
public class HexuAccountService {
 private final HexuStore db;
 public HexuAccountService(HexuStore db){this.db=db;}
 public Map<String,Object> closure(Actor a){db.member(a);long orders=db.jdbc().queryForObject("select count(*) from hx_order where buyer_id=? and status in ('UNPAID','PAID','SHIPPED')",Long.class,a.id);long refunds=db.jdbc().queryForObject("select count(*) from hx_refund where member_id=? and status not in ('SUCCESS','CLOSED','REJECTED')",Long.class,a.id);long balances=db.jdbc().queryForObject("select count(*) from hx_wallet where member_id=? and (available<>0 or frozen<>0)",Long.class,a.id);long agents=db.jdbc().queryForObject("select count(*) from hx_agent where member_id=? and status='ACTIVE'",Long.class,a.id);long pending=db.jdbc().queryForObject("select count(*) from hx_earning e join hx_agent a on a.id=e.agent_id where a.member_id=? and e.status='PENDING'",Long.class,a.id);long points=db.jdbc().queryForObject("select coalesce(sum(available),0) from hx_points where member_id=?",Long.class,a.id);long restricted=db.jdbc().queryForObject("select count(*) from hx_points where member_id=? and (pending_reclaim>0 or frozen=true)",Long.class,a.id);return map("eligible",orders+refunds+balances+agents+pending+restricted==0,"orders",orders,"refunds",refunds,"wallets",balances,"agents",agents,"pendingEarnings",pending,"points",points,"restrictedPoints",restricted);}
 @Transactional public Map<String,Object> close(Actor a,Map<String,Object>b){db.one("select id from hx_member where id=? for update",a.id);Map<String,Object> conditions=closure(a);require(bool(conditions,"eligible"),"请先处理未完成交易、余额、积分限制和代理关系");require(bool(b,"confirm")&&bool(b,"forfeitPoints"),"请确认注销及放弃剩余积分");for(Map<String,Object>p:db.jdbc().queryForList("select * from hx_points where member_id=? order by shop_id for update",a.id))if(number(p,"available")>0)db.points(number(p,"shop_id"),a.id,-number(p,"available"),"CLOSURE_FORFEIT",String.valueOf(a.id),false);db.jdbc().update("update hx_member set name='已注销用户',phone=null,authorized=false,status='CLOSED' where id=?",a.id);db.jdbc().update("delete from hx_session where member_id=?",a.id);db.jdbc().update("update hx_document set status='ARCHIVED' where member_id=? and kind in ('profile','address','cart','favorite','privacy_consent')",a.id);db.audit(a,0,"ACCOUNT_CLOSED",String.valueOf(a.id),conditions,map("status","CLOSED"));return map("status","CLOSED");}
}
